const tok = input.trim().split(/\s+/);
let pos = 0;
const nextInt = () => parseInt(tok[pos++], 10);
const r = nextInt(), c = nextInt();
const m = [];
for (let i = 0; i < r; i++) {
  const row = [];
  for (let j = 0; j < c; j++) row.push(nextInt());
  m.push(row);
}
const zr = new Array(r).fill(false), zc = new Array(c).fill(false);
for (let i = 0; i < r; i++)
  for (let j = 0; j < c; j++)
    if (m[i][j] === 0) { zr[i] = true; zc[j] = true; }
const out = [];
for (let i = 0; i < r; i++) {
  const line = [];
  for (let j = 0; j < c; j++) line.push(zr[i] || zc[j] ? 0 : m[i][j]);
  out.push(line.join(" "));
}
